+export function urlNormalize(input) {
+  if (typeof input !== 'string') {
+    throw new TypeError('Invalid URL: expected string');
+  }
+
+  try {
+    const parsed = new URL(input);
+  } catch (e) {
+    throw new TypeError('Invalid URL: ' + e.message);
+  }
+
+  let url = new URL(input);
+
+  // Lowercase scheme and hostname
+  url.protocol = url.protocol.toLowerCase();
+  url.hostname = url.hostname.toLowerCase();
+
+  // Remove default ports
+  if (url.protocol === 'http:' && url.port === '') {
+    url.port = '';
+  } else if (url.protocol === 'https:' && url.port === '443') {
+    url.port = '';
+  }
+
+  // Remove fragment
+  url.hash = '';
+
+  // Handle trailing slash logic
+  const pathname = url.pathname;
+  let normalizedPathname = pathname;
+
+  // Remove trailing slash only when pathname is exactly / and there is no query
+  if (pathname === '/' && !url.search) {
+    normalizedPathname = '/';
+  } else {
+    // Preserve non-root path slash, remove trailing slash if present but not root
+    if (pathname !== '/') {
+      normalizedPathname = pathname.replace(/\/$/, '');
+    }
+  }
+
+  url.pathname = normalizedPathname;
+
+  // Sort query parameters by key then value using decoded semantic strings while preserving duplicates
+  const searchParams = new URLSearchParams(url.search);
+  const sortedParams = [];
+
+  for (const [key, value] of searchParams.entries()) {
+    sortedParams.push({ key, value });
+  }
+
+  // Sort by key, then by value
+  sortedParams.sort((a, b) => {
+    if (a.key < b.key) return -1;
+    if (a.key > b.key) return 1;
+    if (a.value < b.value) return -1;
+    if (a.value > b.value) return 1;
+    return 0;
+  });
+
+  // Reconstruct search string preserving duplicates
+  const sortedSearchParams = new URLSearchParams();
+  for (const { key, value } of sortedParams) {
+    sortedSearchParams.append(key, value);
+  }
+
+  url.search = sortedSearchParams.toString();
+
+  return url.toString();
+}

